<script setup lang="ts">
import { UserRound } from "lucide-vue-next";
type Company = { id:number; name:string; logo:string; operationalArea:string; nace:string; dangerClass:string; sgk:string; status:"active"|"passive" }
const props=defineProps<{ companies: Company[] }>()
const search=ref(""); const statusFilter=ref<"all"|"active"|"passive">("all"); const currentPage=ref(1); const perPage=ref(10)
const filteredCompanies=computed(()=>{const t=search.value.trim().toLocaleLowerCase("tr-TR");return props.companies.filter(x=>(!t||`${x.name} ${x.operationalArea} ${x.nace} ${x.dangerClass} ${x.sgk}`.toLocaleLowerCase("tr-TR").includes(t))&&(statusFilter.value==="all"||x.status===statusFilter.value))})
const totalPages=computed(()=>Math.max(1,Math.ceil(filteredCompanies.value.length/perPage.value)))
const paginated=computed(()=>filteredCompanies.value.slice((currentPage.value-1)*perPage.value,currentPage.value*perPage.value))
const visiblePages=computed(()=>Array.from({length:Math.min(5,totalPages.value)},(_,i)=>Math.min(Math.max(1,currentPage.value-2)+i,totalPages.value)).filter((p,i,a)=>a.indexOf(p)===i))
const resetFilters=()=>{search.value="";statusFilter.value="all"}; watch([search,statusFilter,perPage],()=>currentPage.value=1)
</script>
<template><div>
<section class="mb-5 rounded-xl border border-gray-200 bg-white p-4 shadow-theme-xs"><div class="grid grid-cols-1 gap-3 md:grid-cols-[minmax(220px,1.2fr)_1fr_auto] md:items-center"><div class="relative"><input v-model="search" type="search" placeholder="Firma ara..." class="h-11 w-full rounded-lg border border-gray-200 bg-white px-3 text-sm outline-none" /></div><div class="relative"><select v-model="statusFilter" class="h-11 w-full appearance-none rounded-lg border border-gray-200 bg-white px-3 pr-9 text-sm"><option value="all">Tümü</option><option value="active">Aktif</option><option value="passive">Pasif</option></select></div><button class="inline-flex h-11 items-center justify-center gap-2 rounded-lg border border-gray-200 bg-white px-4 text-sm font-medium text-gray-600" @click="resetFilters">Filtreleri Temizle</button></div></section>
<section class="flex w-full flex-col overflow-hidden rounded-xl border border-gray-200 bg-white shadow-theme-xs"><div class="overflow-x-auto"><table class="w-full min-w-[980px] text-left"><thead class="border-b border-gray-100 bg-gray-50/70"><tr><th class="px-4 py-4 text-xs font-medium text-gray-500">Firma</th><th class="px-4 py-4 text-xs font-medium text-gray-500">Operasyonel Alan</th><th class="px-4 py-4 text-xs font-medium text-gray-500">NACE Kodu</th><th class="px-4 py-4 text-xs font-medium text-gray-500">Tehlike Sınıfı</th><th class="px-4 py-4 text-xs font-medium text-gray-500">SGK Sicil No</th><th class="px-4 py-4 text-xs font-medium text-gray-500">Durum</th><th class="px-4 py-4 text-right text-xs font-medium text-gray-500">İşlemler</th></tr></thead><tbody class="divide-y divide-gray-100"><tr v-for="company in paginated" :key="company.id"><td class="px-4 py-4"><div class="flex items-center gap-3"><div class="flex h-9 w-9 items-center justify-center overflow-hidden rounded-full border border-gray-200 bg-white p-1.5"><img :src="company.logo" :alt="company.name" class="h-full w-full object-contain" /></div><span class="text-sm font-semibold text-gray-800">{{company.name}}</span></div></td><td class="px-4 py-4 text-sm text-gray-500">{{company.operationalArea || "—"}}</td><td class="px-4 py-4 text-sm text-gray-500">{{company.nace}}</td><td class="px-4 py-4"><DangerClassBadge :danger-class="company.dangerClass" /></td><td class="px-4 py-4 text-sm text-gray-500">{{company.sgk}}</td><td class="px-4 py-4"><span class="inline-flex items-center gap-1.5 rounded-full bg-success-50 px-2.5 py-1 text-xs font-medium text-success-600"><span class="h-1.5 w-1.5 rounded-full bg-success-500"/>Aktif</span></td><td class="px-4 py-4 text-right"><button class="inline-flex h-9 items-center gap-1.5 rounded-lg border border-gray-200 px-3 text-xs font-semibold text-gray-700"><UserRound :size="14"/> Uzman Ata</button></td></tr><tr v-if="!paginated.length"><td colspan="7" class="px-4 py-12 text-center text-sm text-gray-500">Kayıt bulunamadı.</td></tr></tbody></table></div><div class="flex w-full flex-col gap-3 border-t border-gray-100 px-4 py-4 sm:flex-row sm:items-center sm:justify-between"><span class="text-sm text-gray-500">Toplam {{ filteredCompanies.length }} kayıt</span><div class="flex items-center gap-1"><button class="h-9 w-9 rounded-lg border disabled:opacity-40" :disabled="currentPage===1" @click="currentPage--">‹</button><button v-for="page in visiblePages" :key="page" class="h-9 min-w-9 rounded-lg px-2 text-sm" :class="page===currentPage?'bg-brand-500 text-white':'text-gray-600'" @click="currentPage=page">{{page}}</button><button class="h-9 w-9 rounded-lg border disabled:opacity-40" :disabled="currentPage===totalPages" @click="currentPage++">›</button></div><select v-model.number="perPage" class="h-9 rounded-lg border border-gray-200 px-3 text-sm"><option :value="10">10 / sayfa</option><option :value="25">25 / sayfa</option><option :value="50">50 / sayfa</option></select></div></section></div></template>
